def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    Parameters:
        encoded (str): The encoded string representing the mapping source.
        original (str): The original string corresponding to the encoded string.
        message (str): The message to decode.

    Returns:
        str: The decoded message or "Failed" if decoding cannot be performed.
    """
    # Quick sanity check on lengths
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    used_values = set()

    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            if mapping[enc_char] != orig_char:
                return "Failed"
        else:
            if orig_char in used_values:
                # Two encoded chars map to the same original: not bijective
                return "Failed"
            mapping[enc_char] = orig_char
            used_values.add(orig_char)

    # The cipher is assumed to be a full substitution of the 26 letters
    if len(mapping) != 26 or len(used_values) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
